-- Additive migration: content/content_version remain the post and revision store.
CREATE TABLE editorial_category(id text PRIMARY KEY,slug text NOT NULL UNIQUE,name text NOT NULL,description text NOT NULL DEFAULT '',visible boolean NOT NULL DEFAULT true);
CREATE TABLE editorial_tag(id text PRIMARY KEY,slug text NOT NULL UNIQUE,name text NOT NULL,description text NOT NULL DEFAULT '',visible boolean NOT NULL DEFAULT true,merged_into text REFERENCES editorial_tag(id));
CREATE TABLE content_tag(content_id text REFERENCES content(id) ON DELETE CASCADE,tag_id text REFERENCES editorial_tag(id),PRIMARY KEY(content_id,tag_id));
CREATE TABLE article_state(content_id text PRIMARY KEY REFERENCES content(id) ON DELETE CASCADE,state text NOT NULL DEFAULT 'DRAFT' CHECK(state IN ('DRAFT','NEEDS_REVIEW','APPROVED','SCHEDULED','PUBLISHED','ARCHIVED','TRASH')),approved_revision integer,approved_by text,approved_at timestamptz,review_reason text NOT NULL DEFAULT '',reflection_status text NOT NULL DEFAULT 'not_published',reflection_error text);
CREATE TABLE editorial_review(id text PRIMARY KEY,content_id text REFERENCES content(id) ON DELETE CASCADE,revision integer NOT NULL,actor text NOT NULL,decision text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(content_id,revision) REFERENCES content_version(content_id,revision));
ALTER TABLE publish_job DROP CONSTRAINT publish_job_status_check;
ALTER TABLE publish_job ADD CONSTRAINT publish_job_status_check CHECK(status IN ('queued','running','retry','succeeded','failed','cancelled','skipped'));
ALTER TABLE publish_job ADD COLUMN scheduled_at timestamptz;
ALTER TABLE publish_job ADD COLUMN idempotency_key text UNIQUE;
ALTER TABLE publish_job ADD COLUMN lease_token text;
ALTER TABLE publish_job ADD COLUMN lease_until timestamptz;
ALTER TABLE publish_job ADD COLUMN attempts integer NOT NULL DEFAULT 0;
ALTER TABLE publish_job ADD COLUMN next_attempt_at timestamptz;
CREATE INDEX publish_job_due ON publish_job(status,scheduled_at,next_attempt_at);
CREATE TABLE editorial_source(id text PRIMARY KEY,input_url text NOT NULL UNIQUE,final_url text,origin_host text NOT NULL,provider text NOT NULL CHECK(provider IN ('URL_HTML','RSS_ATOM','NAVER_SEARCH','WEB_SEARCH','THREADS','INSTAGRAM')),discovered_via text NOT NULL DEFAULT 'operator',title text NOT NULL DEFAULT '',author text NOT NULL DEFAULT '',published_at timestamptz,modified_at timestamptz,collected_at timestamptz,http_status integer,body_hash text,status text NOT NULL DEFAULT 'UNVERIFIED',terms_status text NOT NULL DEFAULT 'UNVERIFIED',approved boolean NOT NULL DEFAULT false,warnings jsonb NOT NULL DEFAULT '[]',etag text,last_modified text,last_attempt_at timestamptz,created_by text NOT NULL);
CREATE TABLE source_document(id text PRIMARY KEY,source_id text REFERENCES editorial_source(id) ON DELETE CASCADE,body_hash text NOT NULL,excerpt text NOT NULL,safe_html text NOT NULL DEFAULT '',segments jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,UNIQUE(source_id,body_hash));
CREATE TABLE editorial_evidence(id text PRIMARY KEY,source_id text REFERENCES editorial_source(id) ON DELETE CASCADE,document_id text REFERENCES source_document(id) ON DELETE CASCADE,claim text NOT NULL,quote text NOT NULL,start_offset integer NOT NULL,end_offset integer NOT NULL,conditions text NOT NULL DEFAULT '',uncertainty text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'NEEDS_REVIEW',verified_at timestamptz,created_by text NOT NULL);
CREATE TABLE topic_candidate(id text PRIMARY KEY,title text NOT NULL,question text NOT NULL,audience text NOT NULL,service_ids jsonb NOT NULL DEFAULT '[]',required_evidence text NOT NULL,intent text NOT NULL DEFAULT 'CREATE',event_key text,content_id text REFERENCES content(id),source_ids jsonb NOT NULL DEFAULT '[]',status text NOT NULL DEFAULT 'OPEN',notes text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX candidate_event_intent ON topic_candidate(event_key,question) WHERE event_key IS NOT NULL;
CREATE TABLE editorial_config(id text PRIMARY KEY CHECK(id='editorial'),body jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE editorial_profile(id text PRIMARY KEY,version integer NOT NULL,body jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE generation_job(id text PRIMARY KEY,idempotency_key text NOT NULL UNIQUE,kind text NOT NULL,status text NOT NULL DEFAULT 'QUEUED',stage text NOT NULL DEFAULT 'WAITING',input jsonb NOT NULL,proposal jsonb,base_content_id text REFERENCES content(id),base_revision integer,actor text NOT NULL,error_code text,error_message text,attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),lease_token text,lease_until timestamptz,created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz);
CREATE INDEX generation_job_queue ON generation_job(status,next_attempt_at,lease_until);
CREATE TABLE editorial_usage(id text PRIMARY KEY,job_id text REFERENCES generation_job(id),stage text NOT NULL,attempt integer NOT NULL,feature text NOT NULL DEFAULT 'insights',model text NOT NULL,currency text NOT NULL,reserved numeric(16,8) NOT NULL,estimated numeric(16,8),input_tokens integer,output_tokens integer,pricing jsonb NOT NULL,status text NOT NULL DEFAULT 'RESERVED',duration_ms integer,request_id text,error_code text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,stage,attempt));
CREATE TABLE editorial_run(id text PRIMARY KEY,run_key text NOT NULL UNIQUE,kind text NOT NULL,status text NOT NULL,detail jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE editorial_cache_epoch(id text PRIMARY KEY CHECK(id='public'),revision bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO editorial_cache_epoch(id) VALUES('public');
CREATE TABLE article_comment(id text PRIMARY KEY,content_id text REFERENCES content(id) ON DELETE CASCADE,parent_id text REFERENCES article_comment(id),nickname text NOT NULL,body text NOT NULL,password_hash text,official_actor text,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','HIDDEN','SPAM','DELETED')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX article_comment_public ON article_comment(content_id,status,parent_id,created_at);
CREATE TABLE content_reaction(target_type text NOT NULL CHECK(target_type IN ('article','comment')),target_id text NOT NULL,visitor_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(target_type,target_id,visitor_id));
CREATE TABLE comment_report(id text PRIMARY KEY,comment_id text REFERENCES article_comment(id) ON DELETE CASCADE,visitor_id text NOT NULL,reason text NOT NULL,status text NOT NULL DEFAULT 'OPEN',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(comment_id,visitor_id));
INSERT INTO article_state(content_id,state,approved_revision,reflection_status) SELECT id,CASE WHEN archived THEN 'ARCHIVED' WHEN published IS NOT NULL THEN 'PUBLISHED' ELSE 'DRAFT' END,published_revision,CASE WHEN published IS NOT NULL THEN 'serving_ready' ELSE 'not_published' END FROM content WHERE kind='article';
ALTER TABLE article_state ADD CONSTRAINT article_approval_version FOREIGN KEY(content_id,approved_revision) REFERENCES content_version(content_id,revision);
ALTER TABLE article_state ADD CONSTRAINT article_approval_required CHECK(state NOT IN ('APPROVED','SCHEDULED') OR (approved_revision IS NOT NULL AND approved_by IS NOT NULL AND approved_at IS NOT NULL));
ALTER TABLE source_document ADD CONSTRAINT source_document_pair UNIQUE(source_id,id);
ALTER TABLE editorial_evidence ADD CONSTRAINT evidence_source_document FOREIGN KEY(source_id,document_id) REFERENCES source_document(source_id,id) ON DELETE CASCADE;
ALTER TABLE editorial_evidence ADD CONSTRAINT evidence_offsets CHECK(start_offset>=0 AND end_offset>start_offset);
ALTER TABLE article_comment ADD CONSTRAINT comment_article_pair UNIQUE(content_id,id);
ALTER TABLE article_comment ADD CONSTRAINT comment_parent_article FOREIGN KEY(content_id,parent_id) REFERENCES article_comment(content_id,id);
ALTER TABLE editorial_usage ADD CONSTRAINT usage_nonnegative CHECK(reserved>=0 AND (estimated IS NULL OR estimated>=0) AND (input_tokens IS NULL OR input_tokens>=0) AND (output_tokens IS NULL OR output_tokens>=0) AND attempt>=1 AND (duration_ms IS NULL OR duration_ms>=0));
ALTER TABLE editorial_usage ADD CONSTRAINT usage_status CHECK(status IN ('RESERVED','SETTLED','UNKNOWN','RELEASED'));
ALTER TABLE generation_job ADD CONSTRAINT generation_status CHECK(status IN ('QUEUED','RUNNING','RETRY','SUCCEEDED','FAILED','CANCELLED','NEEDS_CONFIGURATION','NEEDS_SOURCE','SKIPPED'));
ALTER TABLE publish_job ADD COLUMN review_id text REFERENCES editorial_review(id);
ALTER TABLE publish_job ADD COLUMN db_committed_at timestamptz;
INSERT INTO schema_migration(version) VALUES('002');
